/* Preserve the connected model and apply the current Figma layouts. */
const designSyncBase={nav:sfNav,organizer:organizerPortal,guest:guestPortal,availability:adminAvailability,review:guestReview,sign:guestSign,payment:guestPayment};
guestHeader=function(){const view=state.ui.guest;if(['organizer-portal','organizer','review','sign','payment','confirmed'].includes(view)){state.ui.portalRole='organizer';if(['review','confirmed'].includes(view))state.ui.portalPage='overview';else if(view==='sign')state.ui.portalPage='documents';else if(view==='payment')state.ui.portalPage='billing';return portalHeader();}if(['guest-portal','guest-pass','service-sent'].includes(view)){state.ui.portalRole='guest';return portalHeader();}return '<header class="guest-header">'+img('0d92a.svg','Booking Ninjas')+'</header>';};
sfNav=function(){const view=state.ui.admin,active=['reservation','individual-list','individual-detail'].includes(view)?'Reservations':['contacts','connected-contact'].includes(view)?'Contacts':view==='availability'?'Availability':view==='invoice'?'BN Invoices':view?.startsWith('service')?'Request Manager':'';return img('49e69.png','Salesforce global header','sf-header')+'<nav class="sf-nav" aria-label="Admin navigation"><div class="sf-brand">'+img('3f889.svg')+'Booking Ninjas</div>'+['Reservations','Contacts','Properties','Rate Controller','Availability','BN Invoices','Request Manager','Control Panel'].map(x=>'<button data-action="nav-'+x.replaceAll(' ','-')+'" class="'+(x===active?'active':'')+'"'+(x===active?' aria-current="page"':'')+(x==='Reservations'?' disabled aria-disabled="true"':' ')+'>'+x+'</button>').join('')+'<button class="sf-edit" data-action="design-edit-navigation" aria-label="Edit navigation">'+img('e7672.svg')+'</button></nav>';};
function designDocument(title,description,status,view,download){return '<article class="portal-doc-card"><div class="portal-doc-preview" aria-hidden="true"><i></i><i></i><i></i><i></i></div><div><h3>'+title+'</h3><p>'+description+'</p>'+v2Pill(status)+'<div class="row">'+(view?button('View',view,'primary'):'')+(download?button('Download',download):'')+'</div></div></article>';}
function designPortalTitle(title,sub,status='',actions=''){return '<div class="pickup-title"><div><h1>'+esc(title)+'</h1><p>'+sub+'</p></div>'+(actions?'<div class="row">'+actions+'</div>':status?v2Pill(status):'')+'</div>';}
organizerPortal=function(){if(!v2Active())return designSyncBase.organizer();const page=state.ui.portalPage||'overview';if(page==='documents')return v2Page(designPortalTitle('Documents','Everything signed or shared for the retreat.')+'<div class="portal-doc-grid">'+designDocument('Banquet Event Order (BEO)','Version 2 · Sep 12, 2026','Final','doc-beo','download-beo')+designDocument('Contract','Signed electronically · Sep 22, 2026','Signed','doc-contract','download-contract')+designDocument('Event agenda','Updated Sep 22, 2026','Shared','','cx-agenda')+designDocument('Group Block approval','GBR-008 · Quote and booking confirmation','Confirmed','portal-organizer-overview','')+'</div>');let html=designSyncBase.organizer();if(page==='overview'){html=html.replace(dateLabel(state.request.start).replace(', 2026','')+'</strong>',dateLabel(state.request.start).replace(', 2026','')+' – '+Number(state.request.end.slice(-2))+'</strong>');html=html.replace('</h1><p>','</h1><p>');html=html.replace('</p></div></div><div class="pickup-summary">','</p></div>'+v2Pill(state.reservation.status)+'</div><div class="pickup-summary">');}return html;};
function designChargeRows(r){const date=dateLabel(state.request.start).replace(/, \d{4}/,''),base=roomRate(r.type)*nights();return [[date,r.type+' · '+nights()+' nights','Stay',money(base),v2Pill(r.paid?'Paid':'Due')],[date,'Tax on stay ('+(state.quote.tax?10:0)+'%)','Stay',money(r.amount-base),v2Pill(r.paid?'Paid':'Due')],[date,'Group meals and meeting hall','Group','Included',v2Pill('Paid by '+state.request.organization)],...requestsFor(r).filter(q=>q.status==='Confirmed').map(q=>[q.when.split(' · ')[0],esc(q.title),'Add-ons',q.amount?money(q.amount):'Included',v2Pill(q.status)]),...guestExtras(r).map(x=>[date,x.title,'Add-ons',money(x.price*1.1),v2Pill((r.extrasPaid||0)>=extrasTotal(r)?'Paid':'Due')]),...ordersFor(r).map(o=>[o.when.split(' · ')[0],o.id+' · '+o.items.map(x=>x.qty+'× '+x.title).join(', '),'Cashier',money(o.total),v2Pill(o.payment==='Room'?'Charged to room':'Paid')])];}
guestPortal=function(){const r=portalGuest(),page=state.ui.portalPage||'stay';if(!r||!['room','payment','charges','documents'].includes(page))return designSyncBase.guest();let body='',title='',sub='',actions='';
 if(page==='room'&&r.paid){title='Your room';sub=r.assigned?'Your room is confirmed. Review the assigned room for your stay.':'Your room is confirmed. The room number is assigned at check-in.';body='<div class="portal-room-columns"><article class="portal-room-card"><div class="portal-room-image" aria-hidden="true"></div><div class="portal-room-content"><h2>'+esc(r.type)+'</h2><div class="grid2">'+detail('Dates',dates()+' · '+nights()+' nights')+detail('Bed',r.type==='Standard Single Room'?'1 single bed · up to 1 guest':r.type==='Cabin'?'Cabin with a double bed · up to 4 guests':'1 double bed · up to 2 guests')+detail('Room number',r.assigned?r.unit:'Assigned at check-in')+detail('Group',esc(state.request.organization)+' · GBR-008')+'</div><div class="row">'+button('Ask for a room change','cx-room-request')+button('Show my check-in pass','cx-pass')+'</div></div></article>'+panel('About your room','<div class="portal-about"><b>Who reserved it</b><p>'+(r.organizerPaid?'Your organizer assigned your room.':'You booked with the group code GBR-008.')+'</p><b>Check-in</b><p>'+dateLabel(state.request.start)+' from 3:00 PM at the Main Lodge Lobby.</p><b>Need something else?</b><p>Ask for a room change and the venue team will reply.</p></div>')+'</div>';}
 else if(page==='room')return designSyncBase.guest();
 else if(page==='documents'){title='Documents';sub='Your confirmation and documents for the retreat.';body='<div class="portal-doc-grid">'+designDocument('Reservation confirmation','#'+r.id+' · '+dates(),r.status,'portal-guest-stay','portal-download')+designDocument('Retreat schedule','Sessions, group meals and activities','Shared','portal-guest-schedule','cx-agenda')+designDocument('Guest stay waiver',r.waiver?'Signed at check-in · '+r.waiver.name:'Sign at the front desk during check-in',r.waiver?'Signed':'Not signed','cx-view-waiver','')+designDocument('Check-in pass','Your personal arrival pass','Ready','cx-pass','')+'</div>';}
 else if(page==='charges'){title='Your charges';sub='What is on your stay, and what is paid by your group.';actions=button('Download receipt','portal-download','primary');body='<div class="portal-charge-columns">'+panel('Charges',table(['DATE','DESCRIPTION','FROM','AMOUNT','STATUS'],designChargeRows(r)))+panel('Summary',line('Stay',money(r.amount))+line('Add-ons',money(stayTotal(r)-r.amount))+line('Total',money(stayTotal(r)),'total')+line('Paid',money(stayPaid(r)))+line('Balance due',money(stayBalance(r)),'total')+'<p class="hint">Charges made during your stay will appear here.</p>'+(stayBalance(r)?button('Pay balance '+money(stayBalance(r)),'cx-guest-pay','primary wide-btn'):''))+'</div>';}
 else {title='Payment';sub='Your room payment and any balance due.';body='<div class="portal-payment-columns"><div class="stack">'+panel('Payment status','<div class="row between">'+v2Pill(stayBalance(r)?'Balance due':'Paid in full')+'<strong>'+money(stayPaid(r))+'</strong></div><p class="mt">'+(r.organizerPaid?'Your room is paid by the organizer.':'Your room was paid at booking.')+'</p><div class="mt">'+button('Download receipt','portal-download')+'</div>')+panel('Payment method','<p>'+(r.organizerPaid?'Paid by '+esc(state.request.organization):'Visa ending 4242')+'</p><p class="mt">'+(r.organizerPaid?'Room charges are on the group invoice.':'Used for your room booking.')+'</p>')+'</div>'+panel('Summary',line('Stay',money(r.amount))+line('Additional charges',money(stayTotal(r)-r.amount))+line('Total',money(stayTotal(r)),'total')+line('Paid',money(stayPaid(r)))+line('Balance due',money(stayBalance(r)),'total')+(stayBalance(r)?button('Pay '+money(stayBalance(r)),'cx-guest-pay','primary wide-btn'):v2Pill('Paid')))+'</div>';}
 return v2Page(designPortalTitle(title,sub,page==='room'?r.status:'',actions)+body);
};
serviceRequestList=function(){const p=ops(),rows=p.requests.filter(q=>!p.requestFilter||p.requestFilter==='All'||q.status===p.requestFilter).map(q=>[esc(q.title),button(v2Full(q.guest),'cx-contact-'+q.guestKey,'link'),button('#'+q.reservationId,'v2-record-'+q.reservationId,'link'),q.when,serviceById(q.serviceId)?.category||'Request',badge(q.status),esc(q.assigned),button(q.status==='New'?'Review':'View','cx-request-'+q.id,'link')]);return '<div class="admin service-admin">'+sfNav()+adminHeader('Request Manager','Open requests','',button('List view','design-request-filter'))+'<div class="admin-main"><section class="service-request-table">'+table(['REQUEST','GUEST','RESERVATION','WHEN','TYPE','STATUS','ASSIGNED TO',''],rows)+'</section></div></div>';};
adminAvailability=function(){let html=designSyncBase.availability();if(v2Active())html=html.replace('Pending Approval</span>','Pending / held for the group</span>');return html;};
function designBookingProgress(step){return '<div class="guest-flow-progress" aria-label="Booking progress">'+['Review','Sign','Pay deposit'].map((label,i)=>'<span class="'+(i<step?'done':i===step?'current':'')+'"><b>'+(i<step?'✓':i+1)+'</b>'+label+'</span>').join('<i></i>')+'</div>';}
function designProgress(html,step){return html.replace('<div class="guest-columns">',designBookingProgress(step)+'<div class="guest-columns">');}
guestReview=function(){return designProgress(designSyncBase.review(),0);};guestSign=function(){return designProgress(designSyncBase.sign(),1);};guestPayment=function(){return designProgress(designSyncBase.payment(),2);};
const designSyncHandle=handle;
handle=function(a,el){if(a==='design-edit-navigation'){return;}if(a==='design-request-filter'){openModal('design-request-filter');return;}if(a==='design-apply-filter'){ops().requestFilter=document.querySelector('[name="design-request-filter"]').value;modal=null;save();render();return;}if(a==='demo-app-guest'&&v2Active()&&state.ui.guest==='mailbox'){return openOrganizerPortal();}return designSyncHandle(a,el);};
const designSyncOverlay=renderOverlay;
renderOverlay=function(){if(modal!=='design-request-filter')return designSyncOverlay();document.body.style.overflow='hidden';$('#overlay').innerHTML='<div class="modal-backdrop"><section class="modal small" role="dialog" aria-modal="true" aria-labelledby="design-filter-title"><button class="modal-close" data-action="close-modal" aria-label="Close">×</button><header class="modal-header" id="design-filter-title">List view</header><div class="modal-content">'+select('Status','design-request-filter',ops().requestFilter||'All',['All','New','Confirmed','Declined'])+'</div><footer class="modal-footer">'+button('Cancel','close-modal')+button('Apply','design-apply-filter','primary')+'</footer></section></div>';};
const blockDetailsHandle=handle;
handle=function(a,el){if(a==='nav-Reservations')return;if(a==='block-open-request-window'){const url=new URL(location.href);url.searchParams.set('record','group-block-request');window.open(url.href,'_blank','noopener');return;}return blockDetailsHandle(a,el);};
if(new URLSearchParams(location.search).get('record')==='group-block-request'&&state.request){state.ui.app='admin';state.ui.admin='request';}
const centerSignatureBlock=adminBlock,centerSignatureOverlay=renderOverlay;
adminBlock=function(){let html=centerSignatureBlock();const q=state.quote;if(!q.venueConfirmed){const note=!q.signature?'Waiting for organizer signature.':!q.paid?'Organizer signed. Waiting for deposit before center signing.':'Organizer signed and deposit received. Ready for center signature.';html=html.replace('Confirm after guest signature and deposit</p>',note+'</p><div class="mt">'+button('Sign & confirm booking','review-booking','primary',!q.signature||!q.paid)+'</div>');html=html.replace('Review & Confirm Booking','Sign & confirm booking');}return html;};
renderOverlay=function(){if(modal!=='review-booking')return centerSignatureOverlay();document.body.style.overflow='hidden';const q=state.quote;$('#overlay').innerHTML='<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="center-sign-title"><button class="modal-close" data-action="close-modal" aria-label="Close">×</button><header class="modal-header" id="center-sign-title">Sign & confirm group booking</header><div class="modal-content">'+detail('Organizer signature',esc(q.signature?.name||'Not signed'))+detail('Deposit',q.paid?money(totals().deposit)+' · Paid':'Awaiting payment')+'<form id="center-sign-form" class="stack">'+field('Center representative signature','centerName','Jordan Reyes','text','required')+check('I have reviewed the contract and confirm this booking.','centerAgree',false,'required')+'</form><div id="wizard-error" class="error"></div></div><footer class="modal-footer">'+button('Cancel','close-modal')+button('Sign & confirm booking','center-sign-confirm','primary',!q.signature||!q.paid)+'</footer></section></div>';};
const centerSignatureHandle=handle;
handle=function(a,el){if(a!=='center-sign-confirm')return centerSignatureHandle(a,el);const f=$('#center-sign-form');if(!f.reportValidity())return;const signer=f.elements.centerName.value.trim();if(!signer){$('#wizard-error').textContent='Enter the center representative name.';return;}transition('venue-confirm');state.quote.venueSignature.name=signer;save();modal=null;render();toast('Center signed and confirmed the booking.');};
render();
